def smallestShortestSupersequence(a, b):
    m, n = len(a), len(b)
    f = [[0] * (n + 1) for _ in range(m + 1)]
    for j in range(n + 1):
        f[m][j] = n - j
    for i in range(m - 1, -1, -1):
        f[i][n] = m - i
        row, nxt = f[i], f[i + 1]
        ai = a[i]
        for j in range(n - 1, -1, -1):
            if ai == b[j]:
                row[j] = 1 + nxt[j + 1]
            else:
                x, y = nxt[j], row[j + 1]
                row[j] = 1 + (x if x < y else y)
    i = j = 0
    out = []
    while i < m and j < n:
        if a[i] == b[j]:
            out.append(a[i])
            i += 1
            j += 1
        else:
            can_a = f[i + 1][j] + 1 == f[i][j]
            can_b = f[i][j + 1] + 1 == f[i][j]
            if can_a and (not can_b or a[i] < b[j]):
                out.append(a[i])
                i += 1
            else:
                out.append(b[j])
                j += 1
    out.append(a[i:])
    out.append(b[j:])
    return "".join(out)
